package com.yeyamo_mobile.api.admin_service.governance;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import com.yeyamo_mobile.api.admin_service.event.AdminEventOutbox;import com.yeyamo_mobile.api.admin_service.service.AuditService;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;
class GovernanceVersioningTest {
 @Test void updateCreatesNextVersionAndHistory(){var settings=mock(PlatformSettingRepository.class);var history=mock(PlatformSettingHistoryRepository.class);var flags=mock(FeatureFlagRepository.class);var flagHistory=mock(FeatureFlagHistoryRepository.class);var audit=mock(AuditService.class);var outbox=mock(AdminEventOutbox.class);var current=new PlatformSettingEntity();current.key="PLATFORM_NAME";current.value="Old";current.type="STRING";current.description="Name";current.version=3;current.updatedBy="old";current.updatedAt=Instant.now();when(settings.findById("PLATFORM_NAME")).thenReturn(Optional.of(current));when(settings.save(any())).thenAnswer(i->i.getArgument(0));when(audit.currentAdminId()).thenReturn(UUID.randomUUID());var service=new GovernanceService(settings,history,flags,flagHistory,audit,outbox);var response=service.updateSetting("PLATFORM_NAME",new GovernanceDtos.SettingUpdateRequest("YeYamo","rename",3),new MockHttpServletRequest());assertEquals(4,response.version());verify(history).save(argThat(h->h.version==4&&"YeYamo".equals(h.value)));}
 @Test void rollbackReusesHistoricalValueAsNewVersion(){var settings=mock(PlatformSettingRepository.class);var history=mock(PlatformSettingHistoryRepository.class);var flags=mock(FeatureFlagRepository.class);var flagHistory=mock(FeatureFlagHistoryRepository.class);var audit=mock(AuditService.class);var outbox=mock(AdminEventOutbox.class);var current=new PlatformSettingEntity();current.key="PLATFORM_NAME";current.value="Current";current.type="STRING";current.description="Name";current.version=5;current.updatedAt=Instant.now();var old=new PlatformSettingHistoryEntity();old.key="PLATFORM_NAME";old.value="Previous";old.type="STRING";old.version=2;when(history.findByKeyAndVersion("PLATFORM_NAME",2)).thenReturn(Optional.of(old));when(settings.findById("PLATFORM_NAME")).thenReturn(Optional.of(current));when(settings.save(any())).thenAnswer(i->i.getArgument(0));when(audit.currentAdminId()).thenReturn(UUID.randomUUID());var service=new GovernanceService(settings,history,flags,flagHistory,audit,outbox);var response=service.rollbackSetting("PLATFORM_NAME",2,"rollback",new MockHttpServletRequest());assertEquals("Previous",response.value());assertEquals(6,response.version());}
}
